  Lemma fmodl_sub_body_spec : forall xhi xlo ex, Isub (xhi, xlo, ex) ->
    match fmodl_sub_body x yhi ylo (xhi, xlo, ex) with
    | inl (xhi', xlo', ex') => Isub (xhi', xlo', ex') /\ ex' = ex - 1
    | inr _ => True
    end.
