Lemma scanexp_eq : forall fuelc f pok,
  scanexp fuelc f pok =
    let '(c, f) := sh_getc f in
    let '(neg, c, f) :=
      if (c =? 43) || (c =? 45) then
        let neg := b2z (c =? 45) in
        let '(c, f) := sh_getc f in
        let f := if negb (isdigitc c) && nz pok then sh_unget f else f in
        (neg, c, f)
      else (0, c, f) in
    scanexp_tail fuelc neg c f.
Proof. intros. reflexivity. Qed.

